def pair(part):return f'<div class="pair"><figure><img src="{P}before-{part}.png"><figcaption>Before</figcaption></figure><figure><img src="{P}after-{part}.png"><figcaption>Updated</figcaption></figure></div>'
h=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>173 · Cooler sheltered masonry</title><style>body{{background:#19191e;color:#eee7df;font:17px/1.55 system-ui;max-width:1500px;margin:28px auto;padding:0 22px}}a{{color:#efbc91}}img{{width:100%;display:block}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:20px}}figure{{margin:10px 0}}figcaption{{color:#c5bbc4}}button{{padding:12px;background:#433137;color:#fff;border:1px solid #957e77;cursor:pointer}}section{{margin:42px 0}}.close{{max-width:1000px}}@media(max-width:700px){{.pair{{grid-template-columns:1fr}}}}</style><h1>173 · Cooler sheltered masonry</h1><p>The existing broad weathered area shifts toward a cooler stone hue while retaining its brightness, texture and coverage. Warm facing remains alongside it.</p><button onclick="pick('after')">Updated</button> <button onclick="pick('before')">Before</button><img id="main" src="{P}after-main.png"><p><a href="{P}main-4k.png">Full 4K render</a> · <a href="{P}scene.blend">Editable scene</a> · <a href="{P}kit.blend">Colosseum kit</a></p><section id="crown" class="close"><h2>Broad sheltered facing</h2>{pair('crown')}</section><section id="detail" class="close"><h2>Left exposed core — preserved</h2>{pair('primary')}</section><section id="right" class="close"><h2>Cooler sheltered masonry</h2>{pair('secondary')}</section><section><h2>Whole landmark</h2>{pair('landmark')}</section><section><h2>Original reference</h2><img src="/art/studies/coliseum-134/analysis/independent/reference-display.png"><p>Your original artwork, created with ChatGPT Images 2.5.</p></section><details><summary>Grayscale</summary>{pair('gray')}</details><p id="status">Working candidate; user approval remains pending.</p><script>function pick(v){{document.getElementById('main').src='{P}'+v+'-main.png'}}</script></html>'''
h=h.replace('Broad sheltered facing','Broad sheltered facing').replace('<h2>Cooler sheltered masonry</h2>','<h2>Right-side damage and weathering — preserved</h2>')
if (O/'kit-proof/primary-painted.png').exists():
 h=h.replace('<section><h2>Original reference</h2>','<section><h2>Editable kit check</h2><p>The changed facing rendered from the saved kit, with its native contact ink.</p><div class="pair"><img src="'+P+'kit-proof/primary-painted.png"><img src="'+P+'kit-proof/primary-clay.png"></div></section><section><h2>Original reference</h2>')
